(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8 + Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x-y)*0.01+t*0.45)*8 + Math.sin((x+y)*0.013-t*0.35)*6;
  const sx = x+wx, sy = y+wy;
  const dx = sx-cx, dy = sy-cy;
  const dist = Math.sqrt(dx*dx+dy*dy);
  const ang = Math.atan2(dy, dx);
  const ka = 6, kAng = Math.round(ang/Math.PI*ka)*Math.PI/ka;
  const kDist = dist;
  const ksx = cx+Math.cos(kAng)*kDist, ksy = cy+Math.sin(kAng)*kDist;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.14, 1.3, 0.8],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.11, 2.1, 1.15]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d1 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((ksx-sX)**2+(ksy-sY)**2);
    aS += Math.sin(d1*f-t*sp)*w;
    iS += Math.sin(d1*f*0.7+t*sp*0.6+1.5)*w;
    aS2 += Math.sin(d2*f*1.3-t*sp*0.8)*w*0.6;
    iS2 += Math.sin(d2*f*0.9+t*sp*0.5+2.0)*w*0.6;
  }
  const act = (aS+aS2)/12.8, inh = (iS+iS2)/12.8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05+t*1.8)*0.15;
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = (Math.sin(dist*0.08+ang*2-t*2.0)+Math.sin(dist*0.03-ang*5+t*1.6))*0.2;
  const sp3 = Math.sin(dist*0.06-ang*7+t*0.9)*0.15;
  const spiral = sp1+sp2+sp3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const pulse = 0.95+Math.sin(t*0.8)*0.05+Math.sin(t*1.3+1)*0.03;
  const raw = (act-inh*0.7+bg*0.3+spiral)*pulse+cell*0.2+micro;
  const reaction = Math.tanh(raw*2.2);
  const laplacian = Math.tanh((Math.sin(sx*0.22+1)*Math.sin(sy*0.22-0.5)+Math.cos((sx-sy)*0.18+t*1.5)*0.7)*2)*0.15;
  const membrane = Math.tanh((reaction+laplacian)*1.8)*0.7+reaction*0.3;
  const v = membrane*0.5+0.5;
  const pal = [
    [5,12,55],[12,45,95],[18,95,125],[25,155,145],[60,185,130],
    [160,200,80],[220,195,60],[230,150,55],[215,100,65],[180,60,75],
    [130,35,70],[70,22,60],[30,15,55],[5,12,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(membrane*Math.PI)*0.18;
  const edge = Math.abs(membrane)>0.65?1.12:Math.abs(membrane)>0.4?1.05:1.0;
  const glow = Math.max(0, 1-Math.abs(membrane))*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
